"use client";
import { applied } from "./style-props.internal";
import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import * as RechartsPrimitive from "recharts";
import type { TooltipValueType } from "recharts";

// Format: { THEME_NAME: CSS_SELECTOR }
const THEMES = { light: "", dark: ".dark" } as const;

const INITIAL_DIMENSION = { width: 320, height: 200 } as const;
type TooltipNameType = number | string;

type ChartConfig = Record<
  string,
  {
    label?: React.ReactNode;
    icon?: React.ComponentType;
  } & (
    | { color?: string; theme?: never }
    | { color?: never; theme: Record<keyof typeof THEMES, string> }
  )
>;

type ChartContextProps = {
  config: ChartConfig;
};

const ChartContext = React.createContext<ChartContextProps | null>(null);

function useChart() {
  const context = React.useContext(ChartContext);

  if (!context) {
    throw new Error("useChart must be used within a <ChartContainer />");
  }

  return context;
}

function ChartContainer({
  id,
  className: _className,
  style,
  xstyle,
  children,
  config,
  initialDimension = INITIAL_DIMENSION,
  ...props
}: Styled<React.ComponentProps<"div">> & {
  config: ChartConfig;
  children: React.ComponentProps<
    typeof RechartsPrimitive.ResponsiveContainer
  >["children"];
  initialDimension?: {
    width: number;
    height: number;
  };
}) {
  const uniqueId = React.useId();
  const chartId = `chart-${id ?? uniqueId.replace(/:/g, "")}`;

  return (
    <ChartContext.Provider value={{ config }}>
      <div
        data-slot="chart"
        data-chart={chartId}
        {...applied(styles.container, xstyle, style, "ariax-chart")}
        {...props}
      >
        <ChartStyle id={chartId} config={config} />
        <RechartsPrimitive.ResponsiveContainer
          initialDimension={initialDimension}
        >
          {children}
        </RechartsPrimitive.ResponsiveContainer>
      </div>
    </ChartContext.Provider>
  );
}

const ChartStyle = ({ id, config }: { id: string; config: ChartConfig }) => {
  const colorConfig = Object.entries(config).filter(
    ([, config]) => config.theme ?? config.color,
  );

  if (!colorConfig.length) {
    return null;
  }

  return (
    <style
      dangerouslySetInnerHTML={{
        __html: Object.entries(THEMES)
          .map(
            ([theme, prefix]) => `
${prefix} [data-chart=${id}] {
${colorConfig
  .map(([key, itemConfig]) => {
    const color =
      itemConfig.theme?.[theme as keyof typeof itemConfig.theme] ??
      itemConfig.color;
    return color ? `  --color-${key}: ${color};` : null;
  })
  .join("\n")}
}
`,
          )
          .join("\n"),
      }}
    />
  );
};

// Preserve Recharts component identity: chart internals recognize these primitives.
const ChartTooltip = RechartsPrimitive.Tooltip as (
  props: Omit<
    React.ComponentProps<typeof RechartsPrimitive.Tooltip>,
    "wrapperClassName" | "labelClassName"
  > & {
    wrapperClassName?: never;
    labelClassName?: never;
  },
) => ReturnType<typeof RechartsPrimitive.Tooltip>;

function ChartTooltipContent({
  active,
  payload,
  className: _className,
  style,
  xstyle,
  indicator = "dot",
  hideLabel = false,
  hideIndicator = false,
  label,
  labelFormatter,
  labelClassName: _labelClassName,
  labelXstyle,
  labelStyle,
  formatter,
  color,
  nameKey,
  labelKey,
}: React.ComponentProps<typeof RechartsPrimitive.Tooltip> &
  Styled<React.ComponentProps<"div">> & {
    labelClassName?: never;
    labelXstyle?: stylex.StyleXStyles;
    labelStyle?: React.CSSProperties;
    hideLabel?: boolean;
    hideIndicator?: boolean;
    indicator?: "line" | "dot" | "dashed";
    nameKey?: string;
    labelKey?: string;
  } & Omit<
    RechartsPrimitive.DefaultTooltipContentProps<
      TooltipValueType,
      TooltipNameType
    >,
    "accessibilityLayer"
  >) {
  const { config } = useChart();

  const tooltipLabel = React.useMemo(() => {
    if (hideLabel || !payload?.length) {
      return null;
    }

    const [item] = payload;
    const key = `${labelKey ?? item?.dataKey ?? item?.name ?? "value"}`;
    const itemConfig = getPayloadConfigFromPayload(config, item, key);
    const value =
      !labelKey && typeof label === "string"
        ? (config[label]?.label ?? label)
        : itemConfig?.label;

    if (labelFormatter) {
      return (
        <div {...applied(styles.label, labelXstyle, labelStyle)}>
          {labelFormatter(value, payload)}
        </div>
      );
    }

    if (!value) {
      return null;
    }

    return (
      <div {...applied(styles.label, labelXstyle, labelStyle)}>{value}</div>
    );
  }, [
    label,
    labelFormatter,
    payload,
    hideLabel,
    labelXstyle,
    labelStyle,
    config,
    labelKey,
  ]);

  if (!active || !payload?.length) {
    return null;
  }

  const nestLabel = payload.length === 1 && indicator !== "dot";

  return (
    <div {...applied(styles.tooltip, xstyle, style, "ariax-chart-tooltip")}>
      {!nestLabel ? tooltipLabel : null}
      <div {...applied(styles.grid)}>
        {payload
          .filter((item) => item.type !== "none")
          .map((item, index) => {
            const key = `${nameKey ?? item.name ?? item.dataKey ?? "value"}`;
            const itemConfig = getPayloadConfigFromPayload(config, item, key);
            const indicatorColor = color ?? item.payload?.fill ?? item.color;

            return (
              <div
                key={index}
                {...applied(
                  [styles.item, indicator === "dot" && styles.center],
                  undefined,
                  undefined,
                  "ariax-chart-tooltip-item",
                )}
              >
                {formatter && item?.value !== undefined && item.name ? (
                  formatter(item.value, item.name, item, index, item.payload)
                ) : (
                  <>
                    {itemConfig?.icon ? (
                      <itemConfig.icon />
                    ) : (
                      !hideIndicator && (
                        <div
                          {...applied(
                            [
                              styles.indicator,
                              indicator === "dot" && styles.dot,
                              indicator === "line" && styles.line,
                              indicator === "dashed" && styles.dashed,
                              nestLabel &&
                                indicator === "dashed" &&
                                styles.nestedDashed,
                            ],
                            undefined,
                            {
                              "--ariax-indicator-color": indicatorColor,
                            } as React.CSSProperties,
                          )}
                        />
                      )
                    )}
                    <div
                      {...applied([
                        styles.valueRow,
                        nestLabel ? styles.end : styles.center,
                      ])}
                    >
                      <div {...applied(styles.grid)}>
                        {nestLabel ? tooltipLabel : null}
                        <span {...applied(styles.muted)}>
                          {itemConfig?.label ?? item.name}
                        </span>
                      </div>
                      {item.value != null && (
                        <span {...applied(styles.value)}>
                          {typeof item.value === "number"
                            ? item.value.toLocaleString()
                            : String(item.value)}
                        </span>
                      )}
                    </div>
                  </>
                )}
              </div>
            );
          })}
      </div>
    </div>
  );
}

const ChartLegend = RechartsPrimitive.Legend as React.MemoExoticComponent<
  (
    props: Omit<
      React.ComponentProps<typeof RechartsPrimitive.Legend>,
      "className"
    > & { className?: never },
  ) => ReturnType<typeof RechartsPrimitive.Legend>
>;

function ChartLegendContent({
  className: _className,
  xstyle,
  style,
  hideIcon = false,
  payload,
  verticalAlign = "bottom",
  nameKey,
}: Styled<React.ComponentProps<"div">> & {
  hideIcon?: boolean;
  nameKey?: string;
} & RechartsPrimitive.DefaultLegendContentProps) {
  const { config } = useChart();

  if (!payload?.length) {
    return null;
  }

  return (
    <div
      {...applied(
        [
          styles.legend,
          verticalAlign === "top" ? styles.legendTop : styles.legendBottom,
        ],
        xstyle,
        style,
        "ariax-chart-legend",
      )}
    >
      {payload
        .filter((item) => item.type !== "none")
        .map((item, index) => {
          const key = `${nameKey ?? item.dataKey ?? "value"}`;
          const itemConfig = getPayloadConfigFromPayload(config, item, key);

          return (
            <div
              key={index}
              {...applied(
                styles.legendItem,
                undefined,
                undefined,
                "ariax-chart-legend-item",
              )}
            >
              {itemConfig?.icon && !hideIcon ? (
                <itemConfig.icon />
              ) : (
                <div
                  {...applied(styles.legendIndicator)}
                  style={{
                    backgroundColor: item.color,
                  }}
                />
              )}
              {itemConfig?.label}
            </div>
          );
        })}
    </div>
  );
}

function getPayloadConfigFromPayload(
  config: ChartConfig,
  payload: unknown,
  key: string,
) {
  if (typeof payload !== "object" || payload === null) {
    return undefined;
  }

  const payloadPayload =
    "payload" in payload &&
    typeof payload.payload === "object" &&
    payload.payload !== null
      ? payload.payload
      : undefined;

  let configLabelKey: string = key;

  if (
    key in payload &&
    typeof payload[key as keyof typeof payload] === "string"
  ) {
    configLabelKey = payload[key as keyof typeof payload] as string;
  } else if (
    payloadPayload &&
    key in payloadPayload &&
    typeof payloadPayload[key as keyof typeof payloadPayload] === "string"
  ) {
    configLabelKey = payloadPayload[
      key as keyof typeof payloadPayload
    ] as string;
  }

  return configLabelKey in config ? config[configLabelKey] : config[key];
}

export {
  type ChartConfig,
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
  ChartLegend,
  ChartLegendContent,
  ChartStyle,
};

type Styled<Props> = Omit<Props, "className" | "style"> & {
  className?: never;
  style?: React.CSSProperties;
  xstyle?: stylex.StyleXStyles;
};

const styles = stylex.create({
  container: {
    display: "flex",
    aspectRatio: "16 / 9",
    justifyContent: "center",
    fontSize: ".75rem",
    lineHeight: "calc(1 / .75)",
  },
  label: { fontWeight: 500 },
  tooltip: {
    display: "grid",
    minWidth: "calc(var(--ariax-spacing, .25rem) * 32)",
    alignItems: "flex-start",
    gap: "calc(var(--ariax-spacing, .25rem) * 1.5)",
    borderRadius: "var(--radius)",
    borderWidth: 1,
    borderStyle: "solid",
    borderColor: "color-mix(in oklab,var(--border) 50%,transparent)",
    backgroundColor: "var(--background)",
    paddingInline: "calc(var(--ariax-spacing, .25rem) * 2.5)",
    paddingBlock: "calc(var(--ariax-spacing, .25rem) * 1.5)",
    fontSize: ".75rem",
    lineHeight: "calc(1 / .75)",
    boxShadow:
      "0 0 0 0 #0000, 0 0 0 0 #0000, 0 0 0 0 #0000, 0 0 0 0 #0000, 0 20px 25px -5px rgb(0 0 0 / .1), 0 8px 10px -6px rgb(0 0 0 / .1)",
  },
  grid: { display: "grid", gap: "calc(var(--ariax-spacing, .25rem) * 1.5)" },
  item: {
    display: "flex",
    width: "100%",
    flexWrap: "wrap",
    alignItems: "stretch",
    gap: "calc(var(--ariax-spacing, .25rem) * 2)",
  },
  center: { alignItems: "center" },
  end: { alignItems: "flex-end" },
  indicator: {
    flexShrink: 0,
    borderRadius: 2,
    borderColor: "var(--ariax-indicator-color)",
    backgroundColor: "var(--ariax-indicator-color)",
  },
  dot: {
    height: "calc(var(--ariax-spacing, .25rem) * 2.5)",
    width: "calc(var(--ariax-spacing, .25rem) * 2.5)",
  },
  line: { width: "calc(var(--ariax-spacing, .25rem) * 1)" },
  dashed: {
    width: 0,
    borderWidth: "1.5px",
    borderStyle: "dashed",
    backgroundColor: "transparent",
  },
  nestedDashed: { marginBlock: "calc(var(--ariax-spacing, .25rem) * 0.5)" },
  valueRow: {
    display: "flex",
    flex: "1 1 0%",
    justifyContent: "space-between",
    lineHeight: 1,
  },
  muted: { color: "var(--muted-foreground)" },
  value: {
    fontFamily: "var(--font-mono)",
    fontWeight: 500,
    color: "var(--foreground)",
    fontVariantNumeric: "tabular-nums",
  },
  legend: {
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    gap: "calc(var(--ariax-spacing, .25rem) * 4)",
  },
  legendTop: { paddingBottom: "calc(var(--ariax-spacing, .25rem) * 3)" },
  legendBottom: { paddingTop: "calc(var(--ariax-spacing, .25rem) * 3)" },
  legendItem: {
    display: "flex",
    alignItems: "center",
    gap: "calc(var(--ariax-spacing, .25rem) * 1.5)",
  },
  legendIndicator: {
    height: "calc(var(--ariax-spacing, .25rem) * 2)",
    width: "calc(var(--ariax-spacing, .25rem) * 2)",
    flexShrink: 0,
    borderRadius: 2,
  },
});

import type { CSSProperties } from "react";
import * as stylex from "@stylexjs/stylex";

// Keep marker classes and native inline styles after the compiled StyleX props.
export function applied(
  base: stylex.StyleXArray<
    | stylex.CompiledStyles
    | null
    | undefined
    | boolean
    | readonly [stylex.CompiledStyles, stylex.InlineStyles]
  >,
  xstyle?: stylex.StyleXStyles,
  style?: CSSProperties,
  marker?: string,
) {
  const props = stylex.props(base, xstyle);
  return {
    className: [marker, props.className].filter(Boolean).join(" "),
    style: { ...props.style, ...style },
  };
}

export function resolveStyle<State>(
  style:
    CSSProperties | ((state: State) => CSSProperties | undefined) | undefined,
  state: State,
) {
  return typeof style === "function" ? style(state) : style;
}

import * as stylex from "@stylexjs/stylex";

// tw-animate-css 1.4.0 (MIT); see the distributed TW-ANIMATE-LICENSE.
const enter = stylex.keyframes({
  from: {
    opacity: "var(--ariax-enter-opacity, 1)",
    transform:
      "translate3d(var(--ariax-enter-x, 0), var(--ariax-enter-y, 0), 0) scale3d(var(--ariax-enter-scale, 1), var(--ariax-enter-scale, 1), var(--ariax-enter-scale, 1)) rotate(0)",
    filter: "blur(0)",
  },
});
const exit = stylex.keyframes({
  to: {
    opacity: "var(--ariax-exit-opacity, 1)",
    transform:
      "translate3d(0, 0, 0) scale3d(var(--ariax-exit-scale, 1), var(--ariax-exit-scale, 1), var(--ariax-exit-scale, 1)) rotate(0)",
    filter: "blur(0)",
  },
});
const pulse = stylex.keyframes({ "50%": { opacity: 0.5 } });
const spin = stylex.keyframes({ to: { transform: "rotate(360deg)" } });

// shadcn 4.21.1 scroll-fade (MIT); SHADCN-LICENSE is distributed by the registry.
const scrollRevealTop = stylex.keyframes({
  // @ts-expect-error StyleX keyframes accepts registered CSS properties; its type omits them.
  from: { "--scroll-fade-t": "0px" },
  to: {
    // @ts-expect-error Registered CSS property.
    "--scroll-fade-t":
      "var(--_scroll-fade-size-t, var(--scroll-fade-size, min(12%, calc(var(--ariax-spacing, .25rem) * 10))))",
  },
});
const scrollRevealBottom = stylex.keyframes({
  from: {
    // @ts-expect-error Registered CSS property.
    "--scroll-fade-b":
      "var(--_scroll-fade-size-b, var(--scroll-fade-size, min(12%, calc(var(--ariax-spacing, .25rem) * 10))))",
  },
  // @ts-expect-error Registered CSS property.
  to: { "--scroll-fade-b": "0px" },
});
const caretBlink = stylex.keyframes({
  "0%,70%,100%": { opacity: 1 },
  "20%,50%": { opacity: 0 },
});
const shimmer = stylex.keyframes({
  from: { backgroundPosition: "100% 0" },
  to: { backgroundPosition: "0 0" },
});

const scrollRevealStart = stylex.keyframes({
  // @ts-expect-error Registered CSS property.
  from: { "--scroll-fade-s": "0px" },
  to: {
    // @ts-expect-error Registered CSS property.
    "--scroll-fade-s":
      "var(--_scroll-fade-size-s, var(--scroll-fade-size, min(12%, calc(var(--ariax-spacing, .25rem) * 10))))",
  },
});
const scrollRevealEnd = stylex.keyframes({
  from: {
    // @ts-expect-error Registered CSS property.
    "--scroll-fade-e":
      "var(--_scroll-fade-size-e, var(--scroll-fade-size, min(12%, calc(var(--ariax-spacing, .25rem) * 10))))",
  },
  // @ts-expect-error Registered CSS property.
  to: { "--scroll-fade-e": "0px" },
});

export const animationStyles = stylex.create({
  activeEnter: {
    animationName: { default: null, ":is([data-active])": enter },
  },
  overlay: {
    animationName: {
      default: null,
      ":is([data-entering])": enter,
      ":is([data-exiting])": exit,
    },
  },
  pulse: { animationName: pulse },
  spin: { animationName: spin },
  drawerOverlay: {
    transitionProperty: "opacity",
    transitionDuration: {
      default: "450ms",
      ":is([data-swiping]):not([data-ending-style])": "0ms",
      ":is([data-ending-style])": "calc(var(--drawer-swipe-strength) * 400ms)",
    },
    transitionTimingFunction: "cubic-bezier(.32,.72,0,1)",
  },
  drawerPopup: {
    transitionProperty: "transform, height, opacity, filter",
    transitionDuration: {
      default: "450ms",
      ":is([data-nested-drawer-swiping],[data-swiping]):not([data-ending-style])":
        "0ms",
      ":is([data-ending-style])": "calc(var(--drawer-swipe-strength) * 400ms)",
    },
    transitionTimingFunction: "cubic-bezier(.22,1,.36,1)",
  },
  drawerContent: {
    transitionProperty: "opacity",
    transitionDuration: "300ms",
    transitionTimingFunction: "cubic-bezier(.45,1.005,0,1.005)",
  },
  // StyleX types currently restrict enum/number animation fields to single values; CSS lists remain intact.
  scrollFade: {
    "--_scroll-fade-size-t":
      "var(--scroll-fade-t-size, var(--scroll-fade-size, min(12%, calc(var(--ariax-spacing, .25rem) * 10))))",
    "--_scroll-fade-size-b":
      "var(--scroll-fade-b-size, var(--scroll-fade-size, min(12%, calc(var(--ariax-spacing, .25rem) * 10))))",
    "--scroll-fade-block":
      "linear-gradient(to bottom, transparent 0, #000 var(--scroll-fade-t, 0px), #000 calc(100% - var(--scroll-fade-b, 0px)), transparent 100%)",
    maskImage: "var(--scroll-fade-mask, var(--scroll-fade-block))",
    maskComposite: "intersect",
    maskRepeat: "no-repeat",
    animationName: {
      default: null,
      "@supports (animation-timeline: scroll())": `${scrollRevealTop}, ${scrollRevealBottom}`,
    },
    animationDuration: {
      default: null,
      "@supports (animation-timeline: scroll())": "1ms, 1ms",
    },
    animationTimingFunction: {
      default: null,
      "@supports (animation-timeline: scroll())": "ease-in-out, ease-in-out",
    },
    animationDelay: {
      default: null,
      "@supports (animation-timeline: scroll())": "0s, 0s",
    },
    animationIterationCount: {
      default: null,
      "@supports (animation-timeline: scroll())": "1, 1" as unknown as number,
    },
    animationDirection: {
      default: null,
      "@supports (animation-timeline: scroll())": "normal, normal" as "normal",
    },
    animationFillMode: {
      default: null,
      "@supports (animation-timeline: scroll())": "both",
    },
    animationPlayState: {
      default: null,
      "@supports (animation-timeline: scroll())":
        "running, running" as "running",
    },
    animationTimeline: {
      default: null,
      "@supports (animation-timeline: scroll())":
        "scroll(self y), scroll(self y)",
    },
    animationRange: {
      default: null,
      "@supports (animation-timeline: scroll())":
        "0 var(--scroll-fade-reveal, calc(var(--ariax-spacing, .25rem) * 24)), calc(100% - var(--scroll-fade-reveal, calc(var(--ariax-spacing, .25rem) * 24))) 100%",
    },
    "--scroll-fade-t": {
      default: null,
      "@supports not (animation-timeline: scroll())":
        "var(--_scroll-fade-size-t)",
    },
    "--scroll-fade-b": {
      default: null,
      "@supports not (animation-timeline: scroll())":
        "var(--_scroll-fade-size-b)",
    },
  },
  scrollFadeInline: {
    "--_scroll-fade-size-s":
      "var(--scroll-fade-s-size, var(--scroll-fade-size, min(12%, calc(var(--ariax-spacing, .25rem) * 10))))",
    "--_scroll-fade-size-e":
      "var(--scroll-fade-e-size, var(--scroll-fade-size, min(12%, calc(var(--ariax-spacing, .25rem) * 10))))",
    "--scroll-fade-inline": {
      default:
        "linear-gradient(to right, transparent 0, #000 var(--scroll-fade-s, 0px), #000 calc(100% - var(--scroll-fade-e, 0px)), transparent 100%)",
      ':where([dir="rtl"], [dir="rtl"] *)':
        "linear-gradient(to left, transparent 0, #000 var(--scroll-fade-s, 0px), #000 calc(100% - var(--scroll-fade-e, 0px)), transparent 100%)",
    },
    maskImage: "var(--scroll-fade-mask, var(--scroll-fade-inline))",
    maskComposite: "intersect",
    maskRepeat: "no-repeat",
    animationName: {
      default: null,
      "@supports (animation-timeline: scroll())": `${scrollRevealStart}, ${scrollRevealEnd}`,
    },
    animationDuration: {
      default: null,
      "@supports (animation-timeline: scroll())": "1ms, 1ms",
    },
    animationTimingFunction: {
      default: null,
      "@supports (animation-timeline: scroll())": "ease-in-out, ease-in-out",
    },
    animationDelay: {
      default: null,
      "@supports (animation-timeline: scroll())": "0s, 0s",
    },
    animationIterationCount: {
      default: null,
      "@supports (animation-timeline: scroll())": "1, 1" as unknown as number,
    },
    animationDirection: {
      default: null,
      "@supports (animation-timeline: scroll())": "normal, normal" as "normal",
    },
    animationFillMode: {
      default: null,
      "@supports (animation-timeline: scroll())": "both",
    },
    animationPlayState: {
      default: null,
      "@supports (animation-timeline: scroll())":
        "running, running" as "running",
    },
    animationTimeline: {
      default: null,
      "@supports (animation-timeline: scroll())":
        "scroll(self inline), scroll(self inline)",
    },
    animationRange: {
      default: null,
      "@supports (animation-timeline: scroll())":
        "0 var(--scroll-fade-reveal, calc(var(--ariax-spacing, .25rem) * 24)), calc(100% - var(--scroll-fade-reveal, calc(var(--ariax-spacing, .25rem) * 24))) 100%",
    },
    "--scroll-fade-s": {
      default: null,
      "@supports not (animation-timeline: scroll())":
        "var(--_scroll-fade-size-s)",
    },
    "--scroll-fade-e": {
      default: null,
      "@supports not (animation-timeline: scroll())":
        "var(--_scroll-fade-size-e)",
    },
  },
  caretBlink: { animationName: caretBlink },
  shimmer: {
    "--ariax-shimmer-spread": "var(--shimmer-spread, calc(3ch + 40px))",
    "--ariax-shimmer-base": "currentColor",
    "--ariax-shimmer-highlight": {
      default:
        "var(--shimmer-color, oklch(from currentColor l c h / calc(alpha * 0.2)))",
      ":is(.dark *)":
        "var(--shimmer-color, oklch(from currentColor max(0.8, calc(l + 0.4)) c h / calc(alpha + 0.4)))",
    },
