  --secondary-foreground: oklch(0.985 0 0);
  --muted: oklch(0.269 0 0);
  --muted-foreground: oklch(0.708 0 0);
  --accent: oklch(0.269 0 0);
  --accent-foreground: oklch(0.985 0 0);
  --destructive: oklch(0.704 0.191 22.216);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.556 0 0);
  --chart-1: oklch(0.87 0 0);
  --chart-2: oklch(0.556 0 0);
  --chart-3: oklch(0.439 0 0);
  --chart-4: oklch(0.371 0 0);
  --chart-5: oklch(0.269 0 0);
  --sidebar: oklch(0.205 0 0);
  --sidebar-foreground: oklch(0.985 0 0);
  --sidebar-primary: oklch(0.488 0.243 264.376);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.269 0 0);
  --sidebar-accent-foreground: oklch(0.985 0 0);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.556 0 0);
}

.ariax-toggle svg {
  pointer-events: none;
  flex-shrink: 0;
}
.ariax-toggle svg:not([class*="size-"]) {
  width: var(--ariax-toggle-icon-size);
  height: var(--ariax-toggle-icon-size);
}

.ariax-tooltip [data-slot="kbd"] {
  position: relative;
  isolation: isolate;
  z-index: 50;
  border-radius: calc(var(--radius) * 0.6);
}
/* Animation variables must not inherit into nested overlays. */
@property --ariax-enter-opacity {
  syntax: "*";
  inherits: false;
  initial-value: 1;
}
@property --ariax-enter-scale {
  syntax: "*";
  inherits: false;
  initial-value: 1;
}
@property --ariax-enter-x {
  syntax: "*";
  inherits: false;
  initial-value: 0;
}
@property --ariax-enter-y {
  syntax: "*";
  inherits: false;
  initial-value: 0;
}
@property --ariax-exit-opacity {
  syntax: "*";
  inherits: false;
  initial-value: 1;
}
@property --ariax-exit-scale {
  syntax: "*";
  inherits: false;
  initial-value: 1;
}

.ariax-typography-list > li {
  margin-top: calc(var(--ariax-spacing, 0.25rem) * 2);
}
